"""Chinese literary assessment pages; reviewer view loads only anonymous material."""
from __future__ import annotations
import html


def literary_page_html(csrf_token: str, csp_nonce: str) -> str:
    return _PAGE.replace("__CSRF__", html.escape(csrf_token, quote=True)).replace("__NONCE__", html.escape(csp_nonce, quote=True))


_PAGE = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>质量评测 · Workspace Studio</title>
<style nonce="__NONCE__">
:root{color-scheme:light;--ink:#243434;--line:#d8dfd8;--green:#2c5f4b}*{box-sizing:border-box}body{margin:0;background:#f5f3ec;color:var(--ink);font:16px/1.7 system-ui,sans-serif}header,main{max-width:1120px;margin:auto;padding:22px}header{border-bottom:1px solid var(--line)}h1{font-size:28px;margin:0}h2{font-size:22px}h3{font-size:18px}.card{background:#fffef9;padding:24px;margin:20px 0;border:1px solid var(--line);border-radius:12px}.row{display:flex;gap:16px;align-items:end;flex-wrap:wrap}.field{display:grid;gap:5px;flex:1;min-width:180px}label{font-weight:600}input,select,textarea,button{font:inherit}input,select,textarea{padding:9px;border:1px solid #aebdb2;border-radius:6px;max-width:100%}textarea{width:100%;min-height:95px}button,.button{border:0;padding:10px 18px;border-radius:6px;background:var(--green);color:white;cursor:pointer;text-decoration:none;display:inline-block}button.secondary{background:#e5eae3;color:var(--ink)}button:disabled{opacity:.5;cursor:default}a{color:var(--green)}.muted{color:#65766e}.notice{padding:14px;background:#e9eee3;border-radius:6px}.error{color:#a32924;white-space:pre-wrap}table{border-collapse:collapse;width:100%;font-size:15px}th,td{border-bottom:1px solid var(--line);padding:9px;text-align:left}.prose{min-height:500px;font:18px/2.05 Georgia,"Noto Serif SC",serif;background:#fffef9}.scoregrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}.check{display:flex;gap:10px;align-items:start}.check input{margin-top:8px}.issue{border-left:4px solid #b09a68;padding:12px;margin:12px 0}pre{white-space:pre-wrap;word-break:break-word}#message{position:sticky;top:0;background:#fff8e5;padding:8px 20px;z-index:2}#message:empty{display:none}footer{margin:30px 0;color:#64736a}@media(max-width:650px){main,header{padding:14px}.card{padding:16px}.prose{min-height:360px}}
.review-fields{border:0;padding:0}</style></head><body><header><h1 id="heading">质量评测</h1><p class="muted">匿名阅读 · 独立评分 · 明确证据与适用范围</p></header><div id="message" role="status"></div><main id="app" aria-live="polite">正在读取评测资料…</main>
<script nonce="__NONCE__">
const csrf="__CSRF__",app=document.getElementById("app"),message=document.getElementById("message");
const parts=location.pathname.split("/"),project=parts[2],api=`/api/projects/${project}/literary`,isReviewer=parts[4]==="review",trialId=parts[5],reviewerId=parts[6],reviewToken=location.hash.slice(1);
let own=null,draft=null,workspace=null,reports=null;
const esc=x=>String(x??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const say=x=>message.textContent=x;
async function request(path,body){const res=await fetch(path,{credentials:isReviewer?"omit":"same-origin",method:body?"POST":"GET",headers:{"Content-Type":"application/json","X-Studio-CSRF":csrf,...(isReviewer?{"X-Literary-Reviewer":reviewToken}:{})},...(body?{body:JSON.stringify(body)}:{})});const data=await res.json();if(!res.ok)throw Error(data.error||"操作失败");return data}
function download(name,value,type="application/json"){const blob=new Blob([typeof value==="string"?value:JSON.stringify(value,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function protect(fn){return async e=>{try{await fn(e)}catch(error){say(error.message)}}}
const stageNames={opening:"开篇诊断",sustained:"持续性诊断",formal:"正式同人验收",crossover:"跨界专项诊断"};
const statusNames={unverified:"未验证",awaiting_reviews:"等待独立评审",pending_resolution:"待处理分歧",passed:"本样本达到内部阈值",needs_revision:"需要修订后重新试写",stale:"已失效，请重建评测"};
function sampleRow(){return `<div class="row sample"><div class="field"><label>来源项目</label><select class="source">${workspace.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.title||p.relative_config)}</option>`).join("")}</select></div><div class="field"><label>起始章</label><input class="start" type="number" min="1" value="1" required></div><div class="field"><label>结束章</label><input class="end" type="number" min="1" value="3" required></div><button type="button" class="remove secondary">移除此样本</button></div>`}
async function admin(){[workspace,reports]=await Promise.all([request("/api/workspace"),request(api)]);app.innerHTML=`<p><a href="/projects/${project}">← 返回项目</a></p><p class="notice">生产协议、人工终稿验收、试写评测和平台预检分别判断。${esc(reports.scope_note)}</p><section class="card"><h2>分别查看质量证据</h2><p>生产协议：${reports.quality_axes.protocol_ready?"可用":"待修复"} · 人工终稿验收：${reports.quality_axes.author_acceptance_ready?"当前已覆盖":"未完成或失效"} · 正式试写验收：${reports.formal_acceptance?"有当前有效样本":"未验证"}</p><details><summary>现有平台预检结果</summary>${Object.entries(reports.quality_axes.platform_preflights).map(([target,v])=>`<p>${target==="qidian_male"?"起点":target==="fanqie_free"?"番茄":esc(target)}：${v.report_stale?"报告已失效":v.policy_verification_required?"需核对平台规则":v.blocking?"存在待处理项":v.report_file?"已有当前预检报告":"尚未生成报告"} <a href="/projects/${project}/publication">查看发布中心</a></p>`).join("")}</details></section><section class="card"><h2>创建评测</h2><p class="muted">选择已完成关闭流程的章节。正文、审稿证据与来源绑定由控制面核对；本页不会自动开书或批准正文。</p><form id="create"><div class="row"><div class="field"><label>评测名称（英文 ID）</label><input name="trial_id" pattern="[A-Za-z0-9][A-Za-z0-9._\\-]{0,63}" required placeholder="opening-september"></div><div class="field"><label>阶段</label><select name="stage"><option value="opening">开篇诊断 · 每份 3 章</option><option value="sustained">持续性诊断 · 每份 10 章</option><option value="formal">正式同人验收 · 两类路线各 20 章</option><option value="crossover">跨界专项诊断 · 连续章节范围</option></select></div></div><div id="samples">${sampleRow()}</div><p class="row"><button id="add-sample" type="button" class="secondary">添加样本项目</button><button>核对证据并创建匿名包</button></p></form></section><section class="card"><h2>现有评测</h2>${reports.trials.length?reports.trials.map(t=>`<article class="issue"><h3>${esc(t.trial_id)} · ${esc(statusNames[t.status]||t.status)}</h3>${t.current?`<p>已提交 ${t.reviewers_submitted.length}/3 位 · 阶段 ${esc(stageNames[t.stage]||t.stage)}</p><button data-report="${esc(t.trial_id)}">阅读报告与处理分歧</button> <a class="button" href="${api}/${esc(t.trial_id)}/export-pack">导出匿名阅读包</a><form class="add-reviewer row" data-trial="${esc(t.trial_id)}"><div class="field"><label>评审人代号</label><input name="reviewer_id" required pattern="[A-Za-z0-9][A-Za-z0-9._\\-]{0,63}" placeholder="reader-1"></div><button>创建独立评审入口</button></form><div class="reviewer-link"></div>`:`<p class="error">${esc(t.reason)}</p>`}</article>`).join(""):"<p>尚无真实试写证据，文学质量为未验证。</p>"}</section><section class="card"><h2>记录本项目人工工作耗时（可选）</h2><p class="muted">记录对应已关闭章节的实际审阅与修改时间，留空为未知。耗时用于观察人工负担，不替代阅读评分。</p><form id="effort" class="row"><div class="field"><label>章节</label><input name="chapter_number" type="number" min="1" required></div><div class="field"><label>审阅分钟</label><input name="human_review_minutes" type="number" min="0"></div><div class="field"><label>修改分钟</label><input name="human_edit_minutes" type="number" min="0"></div><button>保存本人耗时记录</button></form></section><section id="report"></section><footer>默认试写顺序：原创与两类同人各 3 章 → 两类同人各 10 章 → 各 20 章及三人独立评审。跨界诊断须另行覆盖三种拓扑，顺序诸天须包含换卷后的后果承接。</footer>`;
document.getElementById("effort").onsubmit=protect(async e=>{e.preventDefault();const data=new FormData(e.target);await request(api+"/effort-record",{chapter_number:Number(data.get("chapter_number")),human_review_minutes:data.get("human_review_minutes")===""?null:Number(data.get("human_review_minutes")),human_edit_minutes:data.get("human_edit_minutes")===""?null:Number(data.get("human_edit_minutes"))});say("人工耗时已记录，并绑定当前终稿。");await admin()});document.getElementById("samples").onclick=e=>{if(e.target.classList.contains("remove")&&document.querySelectorAll(".sample").length>1)e.target.closest(".sample").remove()};document.getElementById("add-sample").onclick=()=>document.getElementById("samples").insertAdjacentHTML("beforeend",sampleRow());document.getElementById("create").onsubmit=protect(async e=>{e.preventDefault();const data=new FormData(e.target),samples=[...document.querySelectorAll(".sample")].map(r=>({project_id:r.querySelector(".source").value,chapter_start:Number(r.querySelector(".start").value),chapter_end:Number(r.querySelector(".end").value)}));await request(api+"/create",{trial_id:data.get("trial_id"),stage:data.get("stage"),samples});say("匿名包已创建，请邀请三位未参与创作的独立人类评审。");await admin()});document.querySelectorAll(".add-reviewer").forEach(f=>f.onsubmit=protect(async e=>{e.preventDefault();const t=f.dataset.trial,r=new FormData(f).get("reviewer_id"),result=await request(api+"/reviewer-add",{trial_id:t,reviewer_id:r});const url=`${location.origin}/projects/${project}/literary/review/${t}/${r}#${result.review_token}`;f.nextElementSibling.innerHTML=`<p>仅交给此评审人（请使用同机独立浏览器配置或隐私窗口）：<a target="_blank" rel="noopener" href="${esc(url)}">打开匿名评审入口 ${esc(r)}</a></p><input aria-label="独立评审链接" readonly value="${esc(url)}">`;say("入口凭证只在此显示；请保存链接。外部评审可使用导出的匿名包和个人评分文件。")}));document.querySelectorAll("[data-report]").forEach(b=>b.onclick=()=>renderReport(reports.trials.find(t=>t.trial_id===b.dataset.report)))}
function renderReport(report){const box=document.getElementById("report");box.className="card";box.innerHTML=`<h2>${esc(report.trial_id)} · 评测报告</h2><p class="notice">${esc(statusNames[report.status]||report.status)}。${esc(report.scope_note)}</p>${report.entries.map(e=>`<h3>${esc(e.blind_id)}</h3><table><thead><tr><th>指标</th><th>独立分数</th><th>中位数</th><th>阈值</th></tr></thead><tbody>${Object.entries(e.scores).map(([m,v])=>`<tr><td>${esc(report.metrics[m]||m)}</td><td>${v.scores.join(" / ")||"未提交"}</td><td>${v.median??"待三人完成"}</td><td>${v.threshold}</td></tr>`).join("")}</tbody></table>`).join("")}<details><summary>本轮原文问题与评语</summary>${report.entries.map(e=>e.review_notes.map(r=>`<article class="issue"><h4>${esc(e.blind_id)} · ${esc(r.reviewer_id)}</h4><p>${esc(r.notes)}</p>${r.findings.map(f=>`<blockquote>${esc(f.text)}</blockquote><p>${esc(f.note)}</p>`).join("")}</article>`).join("")).join("")}</details><details><summary>逐章人工审阅与修改耗时</summary><table><tr><th>样本／章节</th><th>审阅分钟</th><th>修改分钟</th><th>修复次数</th><th>上下文估计单位</th></tr>${report.author_effort.map(e=>`<tr><td>${esc(e.blind_id)} / ${e.chapter_number}</td><td>${e.human_review_minutes??"未知"}</td><td>${e.human_edit_minutes??"未知"}</td><td>${e.repair_attempts??"未知"}</td><td>${e.context_estimated_units??"未知"}</td></tr>`).join("")}</table></details><p>评审耗时（分钟）：${report.human_review_minutes.map(x=>x??"未知").join(" / ")||"未知"}</p><p><button id="export-report">导出报告 JSON</button></p>${report.issues.length?`<h3>分歧与严重问题</h3><p>处理意见不改变评分或中位数；确认存在的严重问题需要修订和新一轮评测。</p><form id="resolve">${report.issues.map((i,n)=>`<div class="issue"><h4>${esc(i.id)}</h4><pre>${esc(JSON.stringify(i.finding||i.scores,null,2))}</pre><div class="field"><label>处理结果</label><select name="outcome-${n}">${i.kind==="disagreement"?'<option value="acknowledged">记录分歧，保留全部评分</option>':'<option value="needs_revision">问题成立，需要修订</option><option value="not_substantiated">经原文核对，问题不成立</option>'}</select></div><div class="field"><label>原文核对依据与理由</label><textarea name="reason-${n}" required></textarea></div><div class="field"><label>后续修订或观察事项</label><textarea name="follow-${n}" required></textarea></div></div>`).join("")}<div class="field"><label>处理人</label><input name="decided_by" required></div><p><button ${report.missing_reviewers?"disabled":""}>保存处理意见并复算</button></p></form>`:"<p>暂无需要处理的重要分歧。</p>"}`;document.getElementById("export-report").onclick=()=>download(report.trial_id+"-report.json",report);const form=document.getElementById("resolve");if(form)form.onsubmit=protect(async e=>{e.preventDefault();const data=new FormData(form),decisions={};report.issues.forEach((i,n)=>decisions[i.id]={outcome:data.get(`outcome-${n}`),reason:data.get(`reason-${n}`),follow_up:data.get(`follow-${n}`)});const result=await request(api+"/resolve",{trial_id:report.trial_id,submission_sha256:report.submission_sha256,decisions,decided_by:data.get("decided_by")});renderReport(result);say("处理意见已保存，评分保持原值。")});box.scrollIntoView({behavior:"smooth"})}
async function reviewer(){document.getElementById("heading").textContent="独立匿名评审";own=await request(`${api}/${trialId}/review/${reviewerId}`);draft=structuredClone(own.submission?.review||own.draft);renderReviewer()}
function renderReviewer(){const manifest=own.manifest;app.innerHTML=`<p class="notice">评审人 ${esc(reviewerId)} · ${own.submitted?"已独立提交，评分已锁定":"请先独立阅读并评分，再提交。提交前不显示他人的评分或来源项目映射。"}</p><section class="card"><h2>匿名正文</h2><div class="field"><label>选择篇目与章节</label><select id="chapter">${own.chapters.map((c,i)=>`<option value="${i}">${esc(c.blind_id)} · 第 ${c.chapter_number} 章</option>`).join("")}</select></div><p class="muted">可在正文中选中具体问题原文，再填写该段如何损害阅读体验。</p><textarea class="prose" id="prose" readonly aria-label="匿名章节正文"></textarea><details id="reading-basis"></details><div id="passage-form" ${own.submitted?"hidden":""}><div class="row"><div class="field"><label>问题指标</label><select id="finding-metric"></select></div><div class="field"><label>严重程度</label><select id="severity"><option value="minor">一般建议</option><option value="major">严重问题</option><option value="critical">关键阻断问题</option></select></div></div><div class="field"><label>问题与阅读影响</label><textarea id="finding-note"></textarea></div><p><button id="add-finding">将选中原文加入问题记录</button></p></div></section><form id="review-form"><fieldset ${own.submitted?"disabled":""} class="review-fields">${draft.entries.map((entry,index)=>`<section class="card"><h2>${esc(entry.blind_id)} · 独立评分</h2><div class="scoregrid">${Object.entries(entry.scores).map(([metric,value])=>`<div class="field"><label for="score-${index}-${metric}">${esc(manifest.metrics[metric])}</label><input id="score-${index}-${metric}" data-entry="${index}" data-metric="${metric}" type="number" min="1" max="5" step="0.5" value="${value??""}" placeholder="1—5 分" required></div>`).join("")}</div><p class="muted">不适用项：${Object.entries(manifest.entries.find(e=>e.blind_id===entry.blind_id).metric_applicability).filter(([m,v])=>!v.applicable).map(([m,v])=>esc(manifest.metrics[m])+"（"+esc(v.reason)+"）").join("；")||"无"}</p><div class="field"><label>本篇评语与阅读价值</label><textarea data-notes="${index}">${esc(entry.notes)}</textarea></div><div class="findings">${entry.findings.map((f,n)=>`<div class="issue"><strong>第 ${f.chapter_number} 章 · ${esc(f.severity)}</strong><blockquote>${esc(f.text)}</blockquote><p>${esc(f.note)}</p>${own.submitted?"":`<button type="button" class="secondary remove-finding" data-entry="${index}" data-index="${n}">移除此草稿记录</button>`}</div>`).join("")}</div></section>`).join("")}<section class="card"><h2>独立性与提交</h2><div class="field"><label>本人唯一代号（同一评测不重复使用）</label><input id="human-id" required value="${esc(draft.human_instance_id)}"></div><p class="check"><input id="independent" type="checkbox" ${draft.independence_confirmed?"checked":""} required><label for="independent">我是独立人类评审，未参与这些样本的生成或修改，未查看私有项目映射，也未与他人交换本轮评分。</label></p><div class="field"><label>独立评阅说明</label><textarea id="attestation" required>${esc(draft.attestation_note)}</textarea></div><div class="field"><label>本轮阅读与评分耗时（分钟，可留空）</label><input id="minutes" type="number" min="0" value="${draft.review_minutes??""}"></div><p class="row"><button id="save" type="button" class="secondary">保存个人草稿</button><button type="submit">独立提交并锁定评分</button></p></section></fieldset></form><section class="card"><h2>本机与离线评阅</h2><p>匿名包不含项目映射或他人评分。可导出本人评分草稿，在离线阅读后导入；导入只更新个人草稿，提交仍须点击确认。</p><p class="row"><button id="export-draft" class="secondary">导出本人评分文件</button><label>导入本人评分文件 <input id="import-draft" type="file" accept=".json,application/json" ${own.submitted?"disabled":""}></label></p></section>`;
const chapter=document.getElementById("chapter"),prose=document.getElementById("prose"),loadChapter=()=>{const c=own.chapters[Number(chapter.value)],e=manifest.entries.find(e=>e.blind_id===c.blind_id);prose.value=c.body;const basis=c.reading_basis||{},labels={cross_volume_consequences:"跨卷后果",current_canon_time_and_scene:"原著时间与世界条件",approved_divergences:"批准的分歧",character_knowledge_boundaries:"人物知识范围",relationship_stage:"关系阶段",event_dispositions:"原著事件处置",ability_and_crossover_rules:"能力与跨界规则",canon_character_agency:"原著人物自主性",original_contribution:"新增阅读价值",protected_reveals:"保护的揭示",source_identity_notes:"原著身份参考",free_play:"本章自由空间",ending_state:"批准的章末变化"};document.getElementById("reading-basis").innerHTML=Object.keys(basis).length?`<summary>本章批准的基线与规则参考（建议先读正文）</summary>${Object.entries(basis).map(([k,v])=>`<h3>${esc(labels[k]||"基线参考")}</h3>${(Array.isArray(v)?v:[v]).map(x=>`<p>${esc(typeof x==="object"?x.description:x)}</p>`).join("")}`).join("")}`:"";document.getElementById("finding-metric").innerHTML=e.applicable_metrics.map(m=>`<option value="${m}">${esc(manifest.metrics[m])}</option>`).join("")};chapter.onchange=loadChapter;loadChapter();document.getElementById("add-finding").onclick=protect(async()=>{syncDraft();const c=own.chapters[Number(chapter.value)],start=Array.from(prose.value.slice(0,prose.selectionStart)).length,end=Array.from(prose.value.slice(0,prose.selectionEnd)).length,note=document.getElementById("finding-note").value;if(start===end||!note.trim())throw Error("请选中具体原文并填写阅读影响。");draft.entries.find(e=>e.blind_id===c.blind_id).findings.push({chapter_number:c.chapter_number,start,end,text:prose.value.slice(prose.selectionStart,prose.selectionEnd),metric:document.getElementById("finding-metric").value,severity:document.getElementById("severity").value,note});renderReviewer();say("已加入个人草稿，请保存。")});document.querySelectorAll(".remove-finding").forEach(b=>b.onclick=()=>{syncDraft();draft.entries[Number(b.dataset.entry)].findings.splice(Number(b.dataset.index),1);renderReviewer()});document.getElementById("save").onclick=protect(()=>persist(false));document.getElementById("review-form").onsubmit=protect(async e=>{e.preventDefault();await persist(true)});document.getElementById("export-draft").onclick=()=>{if(!own.submitted)syncDraft();download(`${trialId}-${reviewerId}.json`,draft)};document.getElementById("import-draft").onchange=protect(async e=>{const imported=JSON.parse(await e.target.files[0].text());if(imported.reviewer_id!==reviewerId||imported.trial_id!==trialId||imported.pack_hash!==manifest.pack_hash)throw Error("评分文件不属于本评审人或当前匿名包。");await request(api+"/save",{trial_id:trialId,reviewer_id:reviewerId,draft:imported,expected_sha256:own.draft_sha256});await reviewer();say("个人评分草稿已导入，请核对后独立提交。")})}
function syncDraft(){document.querySelectorAll("[data-metric]").forEach(x=>draft.entries[Number(x.dataset.entry)].scores[x.dataset.metric]=x.value===""?null:Number(x.value));document.querySelectorAll("[data-notes]").forEach(x=>draft.entries[Number(x.dataset.notes)].notes=x.value);draft.human_instance_id=document.getElementById("human-id").value;draft.independence_confirmed=document.getElementById("independent").checked;draft.attestation_note=document.getElementById("attestation").value;const minutes=document.getElementById("minutes").value;draft.review_minutes=minutes===""?null:Number(minutes)}
async function persist(submit){syncDraft();await request(api+(submit?"/submit":"/save"),{trial_id:trialId,reviewer_id:reviewerId,draft,expected_sha256:own.draft_sha256});await reviewer();say(submit?"独立评分已提交并锁定。":"个人草稿已保存。")}
(isReviewer?reviewer():admin()).catch(e=>{app.innerHTML='<p class="error">暂时无法读取评测。</p>';say(e.message)});
</script></body></html>'''
